content.content:
using Microsoft.AspNetCore.Mvc;
using Umbraco.Bench.Umbraco.Models.Blocks;

namespace Umbraco.Bench.Umbraco.ViewComponents;

public sealed class HeroViewComponent : ViewComponent
{
    public IViewComponentResult Invoke(HeroModel model) => View(model);
}
namespace Umbraco.Bench.Umbraco.Models.Blocks;

public sealed class HeroModel
{
    public string Heading { get; set; } = string.Empty;
    public string Lede { get; set; } = string.Empty;
    public string? ImageUrl { get; set; }
}
@inherits UmbracoViewPage<BlockGridItem<HeroBlock>>
@{
    var model = new HeroModel
    {
        Heading = Model.Content.Heading ?? string.Empty,
        Lede = Model.Content.Lede ?? string.Empty,
        ImageUrl = Model.Content.BackgroundImage?.GetCropUrl(width: 1600),
    };
}
@await Component.InvokeAsync("Hero", new { model })
@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>
@{
    var model = new ImageBlockModel
    {
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1200),
        Caption = Model.Content.Caption ?? string.Empty,
    };
}
@await Component.InvokeAsync("ImageBlock", new { model })
@model HeroModel

<section class="relative overflow-hidden bg-slate-900">
    @if (!string.IsNullOrEmpty(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="" class="absolute inset-0 h-full w-full object-cover opacity-60" />
    }
    <div class="relative mx-auto max-w-5xl px-4 py-24 text-center">
        <h1 class="text-4xl font-bold tracking-tight text-white sm:text-5xl">@Model.Heading</h1>
        @if (!string.IsNullOrEmpty(Model.Lede))
        {
            <p class="mx-auto mt-4 max-w-2xl text-lg leading-relaxed text-slate-200">@Model.Lede</p>
        }
    </div>
</section>
@model RichTextModel

<div class="mx-auto max-w-3xl px-4 py-8 text-lg leading-relaxed text-slate-700 [&>p]:mb-6 [&>p:last-child]:mb-0">
